package llmverify
import chisel3._
import chisel3.util._
import chisel3.ltl._
import chisel3.ltl.Sequence._

class rollercoasterNumbers extends Module {
  val io = IO(new Bundle {
    val numOut = Output(UInt(16.W))
  })

  // Register to store the current number
  // Use Reg without initialization to simulate non-deterministic initial values
  val numReg = Reg(UInt(16.W))

  // Compute n[i] * 3 + 1
  // tmp = {2'b0,numOut} + {1'b0,numOut,1'b1}
  val tmp = (Cat(0.U(2.W), numReg) + Cat(0.U(1.W), numReg, 1.U(1.W)))

  // Check overflow: tmp[15+2] | tmp[15+1]
  val overflow = tmp(17) | tmp(16)

  // Next state logic
  when(numReg(0)) { // Odd number
    numReg := Mux(overflow, 0.U, tmp(15,0))
  }.otherwise { // Even number
    numReg := Cat(0.U(1.W), numReg(15,1)) // Divide by 2
  }

  io.numOut := numReg

  // ---------------------------------------------------------------------------
  // Formal Verification Assertions
  // ---------------------------------------------------------------------------

  // Property 1: Even number property — when numReg is even, the next value must
  // equal numReg / 2 (i.e., right-shift by 1 with zero-extension).
  val isEven = !numReg(0)
  val halfNum = Cat(0.U(1.W), numReg(15, 1))
  AssertProperty(isEven |-> Sequence(numReg === halfNum).delay(1),
    None, None, Some("even_next_is_half"))

  // Property 2: Odd with no overflow — when numReg is odd and the 3x+1
  // computation does not overflow 16 bits, the next value must equal tmp(15,0).
  val isOdd = numReg(0)
  val noOverflow = !overflow
  AssertProperty((isOdd && noOverflow) |-> Sequence(numReg === tmp(15, 0)).delay(1),
    None, None, Some("odd_no_overflow_next_is_3x_plus_1"))

  // Property 3: Odd with overflow — when numReg is odd and the 3x+1
  // computation overflows 16 bits, the next value must be 0.
  AssertProperty((isOdd && overflow) |-> Sequence(numReg === 0.U).delay(1),
    None, None, Some("odd_overflow_next_is_zero"))

  // Property 4: Overflow flag correctness — overflow must be true exactly when
  // bit 16 or bit 17 of tmp is set (i.e., the multiplication exceeds 16 bits).
  AssertProperty(overflow === (tmp(17) || tmp(16)),
    None, None, Some("overflow_flag_correct"))

  // Property 5: Liveness — the sequence eventually reaches 0.  Since the
  // Collatz-like process strictly decreases even numbers and overflow resets
  // odd numbers that grow too large, every starting value reaches 0 within a
  // bounded number of steps.  Use a relaxed liveness bound of 2^16 steps,
  // which is more than enough for any 16-bit starting value to converge.
  val countDown = RegInit(0.U(16.W))
  val started = RegInit(false.B)
  when(!started) {
    started := true.B
  }
  // While numReg is non-zero, count down from the max bound.
  when(numReg =/= 0.U) {
    countDown := countDown + 1.U
  }
  // If numReg stays non-zero for too long, something is wrong.
  // assertLivenessTimer is not available without ChiselFV trait,
  // so use an explicit counter check.
  when(countDown === 65535.U) {
    assert(numReg === 0.U, "Liveness: numReg did not reach 0 within 65535 cycles")
  }
}

object VerilogGenerator extends App {
  emitVerilog(new rollercoasterNumbers(), args)
}

package llmverify
import chisel3._
import chisel3.util._
import chisel3.ltl._
import chisel3.ltl.Sequence._

class rollercoasterNumbers extends Module {
  val io = IO(new Bundle {
    val numOut = Output(UInt(16.W))
  })

  // Register to store the current number
  // Use Reg without initialization to simulate non-deterministic initial values
  val numReg = Reg(UInt(16.W))

  // Compute n[i] * 3 + 1
  // tmp = {2'b0,numOut} + {1'b0,numOut,1'b1}
  val tmp = (Cat(0.U(2.W), numReg) + Cat(0.U(1.W), numReg, 1.U(1.W)))

  // Check overflow: tmp[15+2] | tmp[15+1]
  val overflow = tmp(17) | tmp(16)

  // Next state logic
  when(numReg(0)) { // Odd number
    numReg := Mux(overflow, 0.U, tmp(15,0))
  }.otherwise { // Even number
    numReg := Cat(0.U(1.W), numReg(15,1)) // Divide by 2
  }

  io.numOut := numReg

  // --------------------------------------------------------------------------
  // Formal Verification Assertions (Chisel LTL)
  // --------------------------------------------------------------------------

  // Property 1: Even-number step correctness
  // When numReg is even, the next-cycle value must equal numReg / 2.
  val isEven = !numReg(0)
  val halfNum = Cat(0.U(1.W), numReg(15, 1))
  AssertProperty(
    isEven |-> Sequence(numReg === halfNum).delay(1),
    None, None, Some("even_next_is_half"))

  // Property 2: Odd-number step (no overflow)
  // When numReg is odd and 3x+1 stays within 16 bits, the next-cycle value
  // must equal tmp(15,0).
  val isOdd = numReg(0)
  val noOverflow = !overflow
  AssertProperty(
    (isOdd && noOverflow) |-> Sequence(numReg === tmp(15, 0)).delay(1),
    None, None, Some("odd_no_overflow_next_is_3x_plus_1"))

  // Property 3: Odd-number step (overflow)
  // When numReg is odd and 3x+1 overflows 16 bits, the next-cycle value
  // must be 0.
  AssertProperty(
    (isOdd && overflow) |-> Sequence(numReg === 0.U).delay(1),
    None, None, Some("odd_overflow_next_is_zero"))

  // Property 4: Overflow flag correctness (combinational)
  // overflow must be true exactly when tmp(17) or tmp(16) is set.
  AssertProperty(overflow === (tmp(17) || tmp(16)), "overflow_flag_correct")

  // Property 5: Bounded liveness — the sequence eventually reaches 0.
  // For any 16-bit starting value, the odd-divide and overflow-reset dynamics
  // converge to 0 within a finite number of steps.  We use a counter that
  // increments while numReg is non-zero; if the counter saturates we require
  // numReg to be 0.
  val livCounter = RegInit(0.U(16.W))
  when(numReg =/= 0.U) {
    livCounter := livCounter + 1.U
  }
  AssertProperty(
    !(livCounter === 65535.U) || (numReg === 0.U),
    "liveness_reaches_zero_within_bound")
}

object VerilogGenerator extends App {
  emitVerilog(new rollercoasterNumbers(), args)
}
